text:
{
  "questions": [
    {
      "n": 1,
      "start": "Combien de jobs d'été ont été attribués",
      "end": "chaque année au sein du \"grand Etat\""
    },
    {
      "n": 2,
      "start": "Parmi les bénéficiaires de ces jobs d'été, combien étaient, au moment de",
      "end": "leur engagement :"
    },
    {
      "n": 3,
      "start": "Le Conseil d'Etat peut-il fournir ces données en chiffres absolus et en",
      "end": "pourcentage, année par année ?"
    },
    {
      "n": 4,
      "start": "Ces statistiques peuvent-elles également être ventilées par département,",
      "end": "office ou entité employeuse du grand Etat ?"
    },
    {
      "n": 5,
      "start": "L'Etat dispose-t-il de statistiques concernant le nombre de candidatures",
      "end": "reçues pour ces jobs d'été, avec la même ventilation selon le lieu de domicile ?"
    },
    {
      "n": 6,
      "start": "Quels sont précisément les critères de sélection appliqués lors de",
      "end": "l'attribution des jobs d'été au sein de l'Etat de Genève ?"
    },
    {
      "n": 7,
      "start": "Existe-t-il des directives, recommandations ou pratiques internes donnant",
      "end": "une priorité :"
    },
    {
      "n": 8,
      "start": "Le Conseil d'Etat peut-il indiquer, parmi les bénéficiaires de jobs d'été,",
      "end": "combien avaient un parent employé par l'Etat de Genève, et ventiler également ces données"
    },
    {
      "n": 9,
      "start": "Plus particulièrement, le Conseil d'Etat peut-il confirmer ou infirmer que",
      "end": "les enfants de collaborateurs frontaliers de l'Etat bénéficient proportionnellement de davantage de jobs d'été"
    },
    {
      "n": 10,
      "start": "Enfin, le Conseil d'Etat considère-t-il que les règles et pratiques",
      "end": "actuellement en vigueur garantissent une égalité d'accès effective et transparente aux jobs d'été proposés par le grand Etat"
    }
  ],
  "answers": [
    {
      "n": 1,
      "start": "Vous trouverez dans le tableau en annexe les chiffres par département, décomposés",
      "end": "selon les informations demandées."
    },
    {
      "n": 2,
      "start": "Concernant la question 2, les données ventilées par lieu de domicile des bénéficiaires",
      "end": "figurent dans le tableau annexé à la présente réponse."
    },
    {
      "n": 3,
      "start": "Vous trouverez dans le tableau en annexe les chiffres en chiffres absolus et en pourcentage",
      "end": "année par année."
    },
    {
      "n": 4,
      "start": "Ces statistiques peuvent-elles également être ventilées par département, office ou entité employeuse du grand Etat ?",
      "end": "Oui, les données sont ventilées par département dans le tableau annexé."
    },
    {
      "n": 5,
      "start": "L'Etat ne dispose pas de statistiques consolidées concernant le nombre de candidatures reçues",
      "end": "pour ces jobs d'été avec la ventilation demandée."
    },
    {
      "n": 6,
      "start": "Les règles ou principes appliqués par les départements dans l'engagement de jobs d'été sont les suivants :",
      "end": "être âgé de 15 ans révolus au minimum et de 25 ans au maximum; être en cours d'études; être de nationalité suisse ou titulaire d'un permis de travail valable; ne pas avoir déjà travaillé au sein du département au cours des années précédentes."
    },
    {
      "n": 7,
      "start": "Il est d'usage de prioriser les candidatures présentant un lien familial avec un membre du personnel",
      "end": "de l'administration pour autant que le nombre de candidatures répondant aux critères soit supérieur au nombre de places disponibles."
    },
    {
      "n": 8,
      "start": "Il n'a pas été possible d'apporter une réponse fiable à partir des données disponibles",
      "end": "dans le respect de la confidentialité des données des personnes concernées."
    },
    {
      "n": 9,
      "start": "Nous pouvons remarquer que les statistiques présentées dans le tableau annexé infirment l'assertion",
      "end": "indiquant que les enfants de collaborateurs frontaliers de l'Etat bénéficient proportionnellement de davantage de jobs d'été."
    },
    {
      "n": 10,
      "start": "Le Conseil d'Etat précise que le processus de recrutement est dénué de biais relatifs au lieu de résidence",
      "end": "des candidates et candidats."
    }
  ],
  "submitter": "Marc Saudan",
  "co_signatories": [],
  "recommendation": "none",
  "reasoning": {
    "start": "En réponse aux questions 1 à 5 concernant le dénombrement, vous trouverez dans le tableau en annexe les chiffres par département, décomposés selon les informations demandées.",
    "end": "Le Conseil d'Etat précise que le processus de recrutement est dénué de biais relatifs au lieu de résidence des candidates et candidats."
  }
}
